#!/usr/bin/env python3
# ruff: noqa: E501
# Generated by gatekeeper / py-apply (secret-scan target).
#
# One gate with two file lists: every Git tracked file for CI, only the staged
# A/C/M files for the commit hook. Written as a script because the shell form of
# the gate is a pipeline, and Windows has no xargs:
#   git ls-files -z | xargs -0 uv run --locked detect-secrets-hook --baseline .secrets.baseline
#
#   uv run --locked python scripts/secret_scan.py
#   uv run --locked python scripts/secret_scan.py --staged
#
# Standard library only: Python 3.11+ on Linux, macOS and Windows.
from __future__ import annotations

import argparse
import contextlib
import os
import subprocess
import sys

BASELINE_DEFAULT = ".secrets.baseline"
# The argv the course's pipeline builds by hand, kept as a list so no shell is
# involved: uv run --locked detect-secrets-hook --baseline .secrets.baseline <files...>
HOOK_PREFIX = ["uv", "run", "--locked", "detect-secrets-hook"]


def _hook_prefix() -> list[str]:
    """Prefer the project venv's console script; fall back to `uv run`.

    为什么不让 `uv run` 当唯一入口：`uv` 每次启动都要先初始化它的缓存目录
    （本机是 `D:\\uv-cache\\sdists-v9\\.git`），在这个仓库上实测会 `拒绝访问
    (os error 5)`——门禁于是以 exit 2 红掉，而那已经不是代码问题。`detect-secrets`
    现在是 dev 依赖，venv 里的 exe 是现成的，直连既绕开缓存初始化也快。
    `uv run` 保留为兜底：没 sync 过的人仍然拿到同一个门禁，只是慢一点。
    """
    bindir = "Scripts" if os.name == "nt" else "bin"
    suffix = ".exe" if os.name == "nt" else ""
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    candidate = os.path.join(root, ".venv", bindir, f"detect-secrets-hook{suffix}")
    return [candidate] if os.path.isfile(candidate) else list(HOOK_PREFIX)


# Printed verbatim. py-pipeline-run.failureKind() buckets by these markers, and a
# gate that could not judge must never be reported as a gate that found a secret.
MISSING_BASELINE_MESSAGE = "No such file or directory: .secrets.baseline"
MISSING_TOOL_MESSAGE = "detect-secrets is not recognized: 请先 uv sync --locked --all-groups"
# uv reports a missing console script as a spawn failure with its own exit code
# (not 127), so the exit code alone cannot tell "not installed" from "found a
# candidate"; these markers are what uv prints in that case.
NOT_INSTALLED_MARKERS = ("Failed to spawn", "not found in PATH")
# uv's cache is machine state, not project state: when it cannot be initialized
# the toolchain never reaches the files, so the gate can never judge anything.
# These lower-cased fragments are what uv prints then (Windows os error 5 =
# access denied, POSIX os error 13 = permission denied).
CACHE_ERROR_MARKERS = ("failed to initialize cache", "os error 5", "os error 13")


def _utf8_stdio() -> None:
    """Windows consoles default to a legacy code page; child output is UTF-8."""
    os.environ.setdefault("PYTHONUTF8", "1")
    os.environ.setdefault("PYTHONIOENCODING", "utf-8")
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is not None:
            with contextlib.suppress(ValueError, OSError):
                reconfigure(encoding="utf-8", errors="replace")


def _git_files(root: str, staged: bool) -> list[str] | None:
    """Git's own file list, NUL-split so a path with spaces stays one path.

    None means Git itself could not answer; the reason has already been printed.
    """
    if staged:
        # git diff --staged --name-only --diff-filter=ACM -z
        argv = ["git", "diff", "--staged", "--name-only", "--diff-filter=ACM", "-z"]
    else:
        # git ls-files -z: tracked files only, so .venv and build output never
        # reach the scanner.
        argv = ["git", "ls-files", "-z"]
    try:
        completed = subprocess.run(argv, cwd=root, capture_output=True, check=False)
    except FileNotFoundError:
        # No Git is an environment problem, not a finding. The phrase
        # "is not recognized as" is what the runner classifies as environment.
        print(
            "git is not recognized as a command: 请先安装 Git 并确认 git --version 可用",
            file=sys.stderr,
        )
        return None
    if completed.returncode != 0:
        print(f"git {' '.join(argv)} failed (exit {completed.returncode})", file=sys.stderr)
        text = completed.stderr.decode("utf-8", errors="replace")
        if text:
            sys.stderr.write(text if text.endswith("\n") else text + "\n")
        return None
    # NUL separated: the trailing separator would otherwise read as one empty
    # path, and an empty path would scan the whole directory.
    text = completed.stdout.decode("utf-8", errors="replace")
    return [path for path in text.split("\0") if path]


def _report_missing_baseline(baseline: str) -> int:
    """One-time setup, then re-run: without a baseline the gate cannot judge."""
    print(MISSING_BASELINE_MESSAGE, file=sys.stderr)
    if baseline != BASELINE_DEFAULT:
        print(f"（本次指定的 baseline：{baseline}）", file=sys.stderr)
    print(f"Secret 检查未就绪：找不到 {baseline}", file=sys.stderr)
    print("只需人工完成一次（之后不再需要）：", file=sys.stderr)
    print("  1) uv run --locked detect-secrets scan > .secrets.baseline", file=sys.stderr)
    print(
        "  2) uv run --locked detect-secrets audit .secrets.baseline   # 逐项 y/n/s/q",
        file=sys.stderr,
    )
    print("  3) 再运行本脚本：uv run --locked python scripts/secret_scan.py", file=sys.stderr)
    print(
        "以后更新误报用 detect-secrets scan --baseline .secrets.baseline"
        "（不要用 > 覆盖，会丢失审核记录）",
        file=sys.stderr,
    )
    return 1


def _report_cache_unavailable() -> int:
    """uv's cache could not be initialized: environment, never a finding."""
    print(
        "Secret 检查未能运行：uv 缓存初始化失败（Failed to initialize cache / os error 5）",
        file=sys.stderr,
    )
    print(
        "这不是 secret 检查的 findings：脚本没有对任何文件做出判断，"
        "不能据此报告「Secret 未通过」。",
        file=sys.stderr,
    )
    print("原因：uv 缓存目录不可写（PermissionError / Access is denied）。", file=sys.stderr)
    print("提示：把 UV_CACHE_DIR 指向一个可写目录后重试，例如：", file=sys.stderr)
    print(
        "  UV_CACHE_DIR=<可写目录> uv run --locked python scripts/secret_scan.py", file=sys.stderr
    )
    print(
        '  PowerShell 快速排查：$env:UV_CACHE_DIR="$env:TEMP\\uv-cache"；'
        "CI 里把 UV_CACHE_DIR 写进 job 的 env。",
        file=sys.stderr,
    )
    return 2


def _run_hook(files: list, baseline: str, root: str, mode: str, report_only: bool = False) -> int:
    """Run detect-secrets-hook on an argv list and pass its exit code through."""
    print(f"==> Secret 检查：{mode} {len(files)} 个文件", flush=True)
    hooks = _hook_prefix() + ["--baseline", baseline]
    shown = (
        " ".join(hooks + list(files))
        if len(files) <= 5
        else f"{' '.join(hooks)} <{len(files)} 个文件>"
    )
    print(f"    $ {shown}", flush=True)
    try:
        # shell=False on purpose: a file name is data, never syntax.
        completed = subprocess.run(
            hooks + list(files),
            cwd=root,
            check=False,
            shell=False,
            capture_output=True,
        )
    except FileNotFoundError:
        # uv itself is missing, so nothing was scanned.
        print(MISSING_TOOL_MESSAGE, file=sys.stderr)
        return 2
    stdout = completed.stdout.decode("utf-8", errors="replace")
    stderr = completed.stderr.decode("utf-8", errors="replace")
    if stdout:
        sys.stdout.write(stdout if stdout.endswith("\n") else stdout + "\n")
    if stderr:
        sys.stderr.write(stderr if stderr.endswith("\n") else stderr + "\n")
    code = completed.returncode
    lowered = (stdout + "\n" + stderr).lower()
    if any(marker in lowered for marker in CACHE_ERROR_MARKERS):
        # An unwritable uv cache is host state: the scanner never saw the files,
        # so this must not read as "found a secret".
        return _report_cache_unavailable()
    if code == 127 or any(marker in stderr for marker in NOT_INSTALLED_MARKERS):
        # The tool is not installed even though the interpreter started: same
        # message as the FileNotFoundError branch, same exit code.
        print(MISSING_TOOL_MESSAGE, file=sys.stderr)
        return 2
    if code == 0:
        print("Secret 检查通过。", flush=True)
        return 0
    if report_only:
        # 报告式：命中数照实打印，但不改退出码。
        # 为什么这个仓库需要它：`.env.example` 的开发 DSN、测试里的占位 key、
        # 文档里的示例凭据会让 hook 稳定命中 40 处；把它们全部内联 allowlist
        # 是噪音，而 `detect-secrets scan` 在本机（Windows / 1.5.0）对同一批文件
        # 返回 0 命中、生成不出 hook 认的 baseline——两边口径不一致，先不拿
        # 一个永远红的门禁教人忽略门禁。要变成阻断式：逐处加
        # `# pragma: allowlist secret`，或在能复现 scan 口径的机器上重建 baseline。
        hits = stdout.count("Location:")
        print(
            f"Secret 检查：report-only，命中 {hits} 处（不阻断；见 docs/部署与回滚.md §3）",
            file=sys.stderr,
        )
        return 0
    print(f"Secret 检查未通过：detect-secrets-hook 返回 {code}", file=sys.stderr)
    # Signals arrive negative; 128+n is the shell's convention for "died on a
    # signal", and anything else stands on its own.
    return code if code >= 0 else 128 - code


def main(argv: list | None = None) -> int:
    _utf8_stdio()
    parser = argparse.ArgumentParser(
        description="Run detect-secrets over Git tracked files, or only the staged ones.",
    )
    parser.add_argument(
        "--staged", action="store_true", help="only files staged for commit (A/C/M)"
    )
    parser.add_argument("--baseline", default=BASELINE_DEFAULT, help="detect-secrets baseline file")
    parser.add_argument(
        "--report-only",
        action="store_true",
        help="print findings but always exit 0 (advisory gate)",
    )
    parser.add_argument(
        "--root", default=".", help="project root to run in (default: current directory)"
    )
    args = parser.parse_args(argv)

    root = os.path.abspath(args.root)
    baseline_path = (
        args.baseline if os.path.isabs(args.baseline) else os.path.join(root, args.baseline)
    )

    # Cheapest precondition first: without a reviewed baseline the hook cannot
    # judge anything, and listing files would only bury that message.
    if not os.path.isfile(baseline_path):
        return _report_missing_baseline(args.baseline)

    raw = _git_files(root, args.staged)
    if raw is None:
        # Git could not list files: environment, not findings.
        return 2
    baseline_rel = os.path.relpath(baseline_path, root).replace(os.sep, "/").lower()
    excluded = {BASELINE_DEFAULT.lower(), baseline_rel}
    # A baseline is generated state; scanning it can only add noise (and it is
    # usually the biggest file in the repository).
    files = [path for path in raw if path.replace("\\", "/").lower() not in excluded]
    if not files:
        what = "暂存区没有新增/复制/修改的文件" if args.staged else "Git 没有跟踪任何文件"
        print(f"没有需要检查的文件（{what}），跳过 Secret 检查。")
        return 0

    mode = "暂存区" if args.staged else "全部跟踪文件"
    return _run_hook(files, args.baseline, root, mode, report_only=args.report_only)


if __name__ == "__main__":
    raise SystemExit(main())
